inline const EncTbl* EncTblOf(const std::wstring& enc) {
    if (enc == L"big5") return &kBig5;
    if (enc == L"shift_jis") return &kSjis;
    if (enc == L"euc_jp") return &kEucJp;
    if (enc == L"euc_kr") return &kEucKr;
    return nullptr;
}
inline uint16_t EncTblLookup(const EncPair* data, int count, uint16_t key) {
    int lo = 0, hi = count - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (data[mid].key == key) return data[mid].cp;
        if (data[mid].key < key) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
